/// delimiting on THIS predicate so they never drift.

pub fn opens_turn(&self) -> bool {
    self.is_genuine_user()
        || self.is_auq_answer_boundary()
        || self.is_plan_rejection_boundary()
        || self.is_peer_message_record()
}

